export function createFormatter(options: { kind: string }): {
  format: (value: unknown) => string;
} {
  const plain = (value: unknown): string => String(value);
  const strategies: Record<string, (value: unknown) => string> = { plain };
  const pick = strategies[options.kind] ?? plain;
  return { format: (value) => pick(value) };
}

