const DAY_MS = 86_400_000;
const URGENT_DAYS = 3;

export function TrialNotice({
  endsAt,
  now,
  label,
}: {
  readonly endsAt: number;
  readonly now: number;
  readonly label: string;
}) {
  const daysLeft = Math.ceil((endsAt - now) / DAY_MS);
  let tone = "calm";
  if (daysLeft <= 0) tone = "expired";
  else if (daysLeft <= URGENT_DAYS) tone = "urgent";
  return <p data-tone={tone}>{label}</p>;
}

