const SPLIT_IN_TWO = 2;

export const indexOfDay = (days, day) => {
  let low = 0;
  let high = days.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / SPLIT_IN_TWO);
    const value = days[middle];
    if (value === day) {
      return middle;
    }
    if (value !== undefined && value < day) {
      low = middle + 1;
    } else {
      high = middle - 1;
    }
  }
  return -1;
};

into.ts:
const SPLIT_IN_TWO = 2;

export const indexOfDay = (days: readonly number[], day: number): number => {
  let low = 0;
  let high = days.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / SPLIT_IN_TWO);
    const value = days[middle];
    if (value === day) {
      return middle;
    }
    if (value !== undefined && value < day) {
      low = middle + 1;
    } else {
      high = middle - 1;
    }
  }
  return -1;
};

