type Listener = (value: number) => void;

const createCell = (initial: number) => {
  let value = initial;
  const listeners = new Set<Listener>();
  return {
    get: (): number => value,
    set: (next: number): void => {
      if (next === value) return;
      value = next;
      listeners.forEach((listener) => {
        listener(next);
      });
    },
    subscribe: (listener: Listener): void => {
      listeners.add(listener);
    },
  };
};

export const editorZoom = createCell(1);
export const previewZoom = createCell(1);

editorZoom.subscribe((value) => {
  previewZoom.set(value);
});
previewZoom.subscribe((value) => {
  editorZoom.set(value);
});

