import { useEffect, useState } from "react";

const PERCENT = 100;

export const useFill = (
  bar: { readonly current: HTMLElement | null },
  durationMs: number,
): number => {
  const [shownPercent, setShownPercent] = useState(0);
  useEffect(() => {
    const element = bar.current;
    if (element === null) return;
    const started = performance.now();
    let frame = 0;
    const step = (time: number) => {
      const part = Math.min(1, (time - started) / durationMs);
      element.style.width = String(part * PERCENT) + "%";
      setShownPercent(Math.round(part * PERCENT));
      if (part < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [bar, durationMs]);
  return shownPercent;
};

