import type { Note } from "./notes";

const BYTE_ORDER_MARK = 0xfeff;

export const importNotes = async (
  file: File,
  save: (notes: readonly Note[]) => Promise<void>,
): Promise<number> => {
  const text = await file.text();
  const body = text.codePointAt(0) === BYTE_ORDER_MARK ? text.slice(1) : text;
  const notes = body
    .split("\n")
    .filter((line) => line.trim() !== "")
    .map((line, index) => ({
      id: `imported-${String(index)}`,
      title: line.trim(),
      body: "",
      createdAt: 0,
    }));
  await save(notes);
  return notes.length;
};

