type Row = { readonly id: string; readonly title: string };

export function Recent() {
  const [rows, setRows] = useState<readonly Row[]>([]);
  useEffect(() => {
    const controller = new AbortController();
    void fetch(RECENT_URL, { signal: controller.signal }).then(
      async (response) => {
