import { newerFirst } from "../newerFirst";

type Stamp = { readonly createdAt: number };

const stamp = () => {
  let stampedAt = 0;
  const builder = {
    at(time: number) {
      stampedAt = time;
      return builder;
    },
    build: (): Stamp => ({ createdAt: stampedAt }),
  };
  return builder;
};

describe("newerFirst with builders", () => {
  it("puts the later one first", () => {
    const older = stamp().at(1).build();
    const newer = stamp().at(2).build();
    expect([older, newer].sort(newerFirst)).toEqual([newer, older]);
  });
});

