const FULL_PERCENT = 100;

type Props = {
  readonly done: number;
  readonly total: number;
  readonly classes?: Partial<ProgressClasses>;
};

export function Progress({ done, total, classes }: Props) {
  const css = mergeStyleMaps<ProgressClasses>(own, classes);
  const percent = total === 0 ? 0 : Math.round((done / total) * FULL_PERCENT);
  return (
    <div
      className={css.track}
      role="progressbar"
      aria-valuenow={percent}
      aria-valuemin={0}
      aria-valuemax={FULL_PERCENT}
    >
      <span className={css.fill} style={{ width: `${String(percent)}%` }} />
    </div>
  );
}

