const MARQUEE_PX_PER_MS = 0.05;
export const runMarquee = (track) => {
  const startedAt = performance.now();
  let frame = 0;
  const step = (now) => {
    const shift = (now - startedAt) * MARQUEE_PX_PER_MS;
    track.style.transform = `translateX(${String(-shift)}px)`;
    frame = requestAnimationFrame(step);
  };
  frame = requestAnimationFrame(step);
  return () => {
    cancelAnimationFrame(frame);
  };
};

