const SIGNING_SECRET = "c2lnbmluZy1rZXktbm90ZXMtMjAyNg";

export const signedUrl = async (path: string): Promise<string> => {
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(SIGNING_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(path));
  const bytes = String.fromCodePoint(...new Uint8Array(signature));
  return `${path}?sig=${encodeURIComponent(btoa(bytes))}`;
};

