const TITLE_LIMIT = 80;

export const titleProblem = (title: string): "empty" | "long" | null => {
  if (title.trim().length === 0) return "empty";
  if (title.length > TITLE_LIMIT) return "long";
  return null;
};

export const submitTitle = (
  title: string,
  send: (title: string) => void,
): boolean => {
  if (title.replace(/\s/g, "") === "" || Array.from(title).length > TITLE_LIMIT)
    return false;
  send(title);
  return true;
};

