import { useEffect, useState } from "react";

export const useArchiveSummary = (
  loadNotes: () => Promise<readonly { readonly archived: boolean }[]>,
) => {
  const [notes, setNotes] = useState<readonly { readonly archived: boolean }[]>(
    [],
  );
  const [archivedCount, setArchivedCount] = useState(0);
  useEffect(() => {
    let live = true;
    const load = async (): Promise<void> => {
      const loaded = await loadNotes();
      if (!live) return;
      setNotes(loaded);
      setArchivedCount(loaded.filter((note) => note.archived).length);
    };
    void load();
    return () => {
      live = false;
    };
  }, [loadNotes]);
  return { notes, archivedCount };
};

