import { useEffect, useState } from "react";
import { z } from "zod";

const TaskDto = z.array(
  z.object({
    id: z.string(),
    title: z.string(),
    dueAt: z.number(),
    done: z.boolean(),
  }),
);

const GRACE_MS = 3_600_000;

type Props = {
  readonly baseUrl: string;
  readonly now: number;
};

export function OverdueTasks({ baseUrl, now }: Props) {
  const [tasks, setTasks] = useState<z.infer<typeof TaskDto>>([]);
  useEffect(() => {
    const controller = new AbortController();
    const load = async (): Promise<void> => {
      const response = await fetch(`${baseUrl}/tasks`, {
        signal: controller.signal,
      });
      setTasks(TaskDto.parse(await response.json()));
    };
    void load();
    return () => {
      controller.abort();
    };
  }, [baseUrl]);
  const overdue = tasks.filter(
    (task) => !task.done && task.dueAt + GRACE_MS < now,
  );
  return (
    <ul>
      {overdue.map((task) => (
        <li key={task.id}>{task.title}</li>
      ))}
    </ul>
  );
}

type Props = {
  readonly note: {
    readonly title: string;
    readonly body: string;
    readonly createdAt: number;
  };
  readonly now: number;
};

const STALE_AFTER_MS = 2_592_000_000;
const SHORT_BODY_CHARS = 20;

export function NoteReviewLine({ note, now }: Props) {
  return (
    <p>
      {note.title}
      {now - note.createdAt > STALE_AFTER_MS &&
        note.body.length < SHORT_BODY_CHARS && <span>Needs review</span>}
    </p>
  );
}

import { useState } from "react";

type Props = {
  readonly publish: () => Promise<void>;
};

export function PublishButton({ publish }: Props) {
  const [status, setStatus] = useState<"idle" | "published" | "failed">("idle");
  const run = async (): Promise<void> => {
    try {
      await publish();
      setStatus("published");
    } catch {
      setStatus("failed");
    }
  };
  return (
    <div>
      <button
        type="button"
        onClick={() => {
          void run();
        }}
      >
        Publish
      </button>
      {status === "failed" && <p role="alert">Publishing failed</p>}
    </div>
  );
}
